<div class="news-admin-header">
    <div><p class="eyebrow">Shortcut directory</p><h1>Quick Links</h1><p class="admin-lead">Manage categorized homepage and footer shortcuts, destinations, icons and display order.</p></div>
    <a class="button" href="<?= e(url('admin/quick-links/create')) ?>"><i class="bi bi-plus-lg"></i> Add quick link</a>
</div>
<form class="panel news-filters" method="get">
    <label class="news-filter-search">Search <input type="search" name="q" value="<?= e($q) ?>" placeholder="Title, URL, category or description"></label>
    <label>Category <select name="category"><option value="">All categories</option><?php foreach ($categories as $item): ?><option value="<?= e($item['category']) ?>" <?= $category === $item['category'] ? 'selected' : '' ?>><?= e($item['category']) ?></option><?php endforeach; ?></select></label>
    <label>Type <select name="link_type"><option value="">All types</option><option value="internal" <?= $linkType === 'internal' ? 'selected' : '' ?>>Internal</option><option value="external" <?= $linkType === 'external' ? 'selected' : '' ?>>External</option></select></label>
    <label>Status <select name="status"><option value="">All statuses</option><?php foreach (['published', 'draft', 'archived'] as $item): ?><option value="<?= $item ?>" <?= $status === $item ? 'selected' : '' ?>><?= ucfirst($item) ?></option><?php endforeach; ?></select></label>
    <button class="button" type="submit">Filter</button><a class="button button-secondary" href="<?= e(url('admin/quick-links')) ?>">Reset</a>
</form>
<section class="panel">
    <div class="panel-heading"><h2>Link directory</h2><span class="panel-note"><?= (int) $pager['total'] ?> links · clear filters to reorder</span></div>
    <div class="table-wrap"><table class="data-table"><thead><tr><th>Link</th><th>Category</th><th>Destination</th><th>Status</th><th></th></tr></thead>
        <tbody id="quickLinksList"><?php foreach ($rows as $row): ?><tr data-id="<?= (int) $row['id'] ?>"><td><span class="drag-handle"><i class="bi bi-grip-vertical"></i></span><span class="quick-icon" style="background: <?= e(preg_match('/^#[0-9A-Fa-f]{3,8}$/', (string) $row['color']) ? $row['color'] : '#0B5CAB') ?>"><i class="bi <?= e($row['icon'] ?: 'bi-link-45deg') ?>"></i></span><strong><?= e($row['title']) ?></strong><?php if ((int) $row['is_featured'] === 1): ?><span class="badge bg-warning text-dark">Featured</span><?php endif; ?><small><?= e($row['subtitle']) ?></small></td><td><?= e($row['category']) ?></td><td><span class="badge bg-light text-dark"><?= e(ucfirst($row['link_type'])) ?></span><small><?= e($row['url']) ?></small></td><td><span class="news-status status-<?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td class="actions"><a href="<?= e(url('admin/quick-links/' . $row['id'] . '/edit')) ?>">Edit</a><a href="<?= e(nav_href($row['url'])) ?>" target="_blank" rel="noopener">Preview</a><form method="post" action="<?= e(url('admin/quick-links/' . $row['id'] . '/delete')) ?>" data-confirm="Delete this quick link?"><?= csrf_field() ?><button type="submit">Delete</button></form></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5">No quick links match the selected filters.</td></tr><?php endif; ?></tbody>
    </table></div>
</section>
<?= render_pagination($pager, '/admin/quick-links', array_filter(['q' => $q, 'category' => $category, 'link_type' => $linkType, 'status' => $status])) ?>
<script src="https://cdn.jsdelivr.net/npm/sortablejs@1.15.6/Sortable.min.js"></script><script>
document.addEventListener('DOMContentLoaded', () => { const list = document.getElementById('quickLinksList'); if (!list || <?= json_encode($q !== '' || $category !== '' || $linkType !== '' || $status !== '' || (int) $pager['pages'] !== 1) ?>) return; new Sortable(list, {animation: 150, handle: '.drag-handle', onEnd: async () => { const response = await fetch(<?= json_encode(url('admin/quick-links/reorder')) ?>, {method: 'POST', headers: {'Content-Type': 'application/json', 'X-CSRF-Token': document.querySelector('meta[name="csrf-token"]')?.content || '', 'Accept': 'application/json'}, body: JSON.stringify({quick_links: [...list.children].filter((row) => row.dataset.id).map((row) => Number(row.dataset.id))})}); const result = await response.json(); if (!response.ok || !result.ok) window.alert(result.message || 'Could not save order.'); }}); });
</script>
